import 'dart:convert';

import 'package:flutter/material.dart';

const String _sangeetaReferenceJpeg = '';

class SangeetaReferenceAvatar extends StatelessWidget {
  const SangeetaReferenceAvatar({
    this.width = 120,
    this.height = 190,
    this.phase = 0,
    super.key,
  });

  final double width;
  final double height;
  final int phase;

  @override
  Widget build(BuildContext context) {
    final image = Image.memory(
      base64Decode(_sangeetaReferenceJpeg),
      width: width,
      height: height,
      fit: BoxFit.cover,
      filterQuality: FilterQuality.high,
      gaplessPlayback: true,
    );

    return RepaintBoundary(
      child: AnimatedSwitcher(
        duration: const Duration(milliseconds: 240),
        switchInCurve: Curves.easeOut,
        switchOutCurve: Curves.easeIn,
        child: Transform.rotate(
          key: ValueKey<int>(phase),
          angle: (phase.isEven ? -1 : 1) * 0.008,
          child: image,
        ),
      ),
    );
  }
}
